package com.yeyamo_mobile.api.feed_service.application.ranking;import java.time.*;import java.util.Map;import org.springframework.stereotype.Component;import com.yeyamo_mobile.api.feed_service.domain.model.FeedCandidate;
@Component public class PersonalizedRankingStrategy implements RankingStrategy{public double score(FeedCandidate c,Map<String,Double>a,Instant now){double hours=Math.max(0,Duration.between(c.post().publishedAt(),now).toMinutes()/60d);double freshness=100d*Math.exp(-hours/48d);double engagement=Math.log1p(c.metric().engagement())*12d;double affinity=Math.min(40,a.getOrDefault(c.post().authorId(),0d)*4d);return freshness+engagement+affinity;}}
